using System;using System.IO;using System.Text;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;
class YouTubeSecurityTests{
 static void Main(){try{Run().GetAwaiter().GetResult();}catch(Exception e){Console.WriteLine(e.GetBaseException().Message);Environment.ExitCode=1;}}
 static async Task Run(){string root=Path.Combine(Environment.CurrentDirectory,"work","youtube-security-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string cookie="SAPISID=unit-test-placeholder; SID=unit-test-placeholder";using(var host=new YouTubeHost(root)){typeof(YouTubeHost).GetMethod("Save",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(host,new object[]{cookie});byte[] encrypted=File.ReadAllBytes(Path.Combine(root,"youtube-session.dpapi"));if(Encoding.UTF8.GetString(encrypted).Contains("unit-test-placeholder"))throw new Exception("Session was not protected");foreach(string url in new[]{"http://music.youtube.com/youtubei/v1/search","https://music.youtube.com.evil.test/youtubei/v1/search","https://example.com/","https://user:password@music.youtube.com/youtubei/v1/search"}){bool rejected=false;try{await host.Handle(new Dictionary<string,object>{{"op","yt-http"},{"url",url},{"method","POST"}});}catch(IOException){rejected=true;}if(!rejected)throw new Exception("Untrusted origin accepted");}await host.Handle(new Dictionary<string,object>{{"op","yt-logout"}});if(File.Exists(Path.Combine(root,"youtube-session.dpapi")))throw new Exception("Logout left the session behind");}Console.WriteLine("PASS: DPAPI protection, origin restrictions and logout");}
}
